import { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from "recharts";
import * as XLSX from "xlsx";

/* ═══════════════════════════════════════
   COÉ BURGUER — BRAND THEME
   Preto + Lima #C9E419
═══════════════════════════════════════ */
const T = {
  bg:       "#060606",
  surf:     "#0C0C0C",
  card:     "#111111",
  cardHi:   "#181818",
  border:   "#202020",
  borderHi: "#2C2C2C",
  accent:   "#C9E419",
  accentDim:"rgba(201,228,25,0.10)",
  accentGlow:"rgba(201,228,25,0.30)",
  text:     "#FFFFFF",
  sub:      "#888888",
  muted:    "#333333",
  green:    "#C9E419",
  greenDim: "rgba(201,228,25,0.10)",
  red:      "#FF4040",
  redDim:   "rgba(255,64,64,0.10)",
  yellow:   "#FFD000",
  yellowDim:"rgba(255,208,0,0.10)",
  blue:     "#60A5FA",
  blueDim:  "rgba(96,165,250,0.10)",
  orange:   "#FF6B35",
};

const PALETTE = ["#C9E419","#FF6B35","#FFFFFF","#FFD000","#FF4040","#60A5FA","#2ECC71"];

/* ═══════════════════════════════════════
   UTILS
═══════════════════════════════════════ */
const fmt  = n => Number(n||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"});
const fmtD = d => { if(!d) return "—"; const[y,m,dd]=d.split("-"); return `${dd}/${m}/${y}`; };
const fmtM = ym => { if(!ym) return ""; const[y,m]=ym.split("-"); return ["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"][+m-1]+" '"+y.slice(2); };
const today= () => new Date().toISOString().split("T")[0];
const dago = n  => { const d=new Date(); d.setDate(d.getDate()-n); return d.toISOString().split("T")[0]; };
const normN= (s="") => s.toLowerCase().replace(/[^a-z0-9\s]/g,"").replace(/\s+/g," ").trim().slice(0,32);
const pBRL = (s="") => { const v=s.replace(/[^\d,\.]/g,""); return v.includes(",")&&v.includes(".")?parseFloat(v.replace(/\./g,"").replace(",","."))||0:v.includes(",")?parseFloat(v.replace(",","."))||0:parseFloat(v)||0; };

const filterP    = (list,s,e) => list.filter(p=>(!s||p.dataEmissao>=s)&&(!e||p.dataEmissao<=e));
const byMonth    = list => { const m={}; list.forEach(p=>{const k=p.dataEmissao?.slice(0,7)||"?";m[k]=(m[k]||0)+p.total;}); return Object.entries(m).sort(([a],[b])=>a.localeCompare(b)).slice(-6).map(([k,v])=>({m:fmtM(k),v})); };
const supplierSt = list => { const m={}; list.forEach(p=>{if(!m[p.emitente])m[p.emitente]={name:p.emitente,total:0,count:0,items:[]};m[p.emitente].total+=p.total;m[p.emitente].count++;m[p.emitente].items.push(...(p.items||[]).map(i=>({...i,supplier:p.emitente,date:p.dataEmissao})));});return Object.values(m).sort((a,b)=>b.total-a.total); };
const productCmp = suppliers => { const m={}; suppliers.forEach(s=>s.items.forEach(item=>{if(!item.desc||item.unit<=0)return;const k=normN(item.desc);if(!m[k])m[k]={desc:item.desc,entries:[]};m[k].entries.push({supplier:s.name,unit:item.unit,date:item.date});})); return Object.values(m).map(p=>{const uniq=[...new Map(p.entries.map(e=>[e.supplier,e])).values()];const prices=uniq.map(e=>e.unit);const mn=Math.min(...prices),mx=Math.max(...prices);return{...p,uniq,min:mn,max:mx,diff:mx-mn,pct:mn>0?(mx-mn)/mn*100:0};}).filter(p=>p.uniq.length>=2).sort((a,b)=>b.pct-a.pct); };
const genAlerts  = purchases => { const hist={}; [...purchases].sort((a,b)=>(a.dataEmissao||"").localeCompare(b.dataEmissao||"")).forEach(p=>{p.items?.forEach(item=>{if(!item.desc||item.unit<=0)return;const k=normN(item.desc);if(!hist[k])hist[k]={desc:item.desc,prices:[]};hist[k].prices.push({unit:item.unit,date:p.dataEmissao,supplier:p.emitente});});}); const alerts=[]; Object.values(hist).forEach(p=>{if(p.prices.length<2)return;const latest=p.prices[p.prices.length-1];const prev=p.prices.slice(0,-1);const avg=prev.reduce((s,x)=>s+x.unit,0)/prev.length;const pct=avg>0?((latest.unit-avg)/avg*100):0;if(pct>8)alerts.push({desc:p.desc,latest:latest.unit,avg,pct,date:latest.date,supplier:latest.supplier,severity:pct>25?"high":pct>15?"medium":"low"});});return alerts.sort((a,b)=>b.pct-a.pct); };
const parseNFe   = (html,url="") => { const doc=new DOMParser().parseFromString(html,"text/html");const body=doc.body?.textContent||"";const items=[];let emitente="Fornecedor";for(const s of[".txtTit",".NomEmi","h4",".empresa","strong","b"]){try{const t=doc.querySelector(s)?.textContent?.trim();if(t&&t.length>2&&t.length<80){emitente=t;break;}}catch(_){}}if(emitente==="Fornecedor"){const t=doc.querySelector("title")?.textContent?.trim();if(t?.length>2)emitente=t.split("|")[0].trim().slice(0,60);}let dataEmissao=today();const dm=body.match(/(\d{2})\/(\d{2})\/(\d{4})/);if(dm)dataEmissao=`${dm[3]}-${dm[2]}-${dm[1]}`;const tables=Array.from(doc.querySelectorAll("table"));for(const tbl of tables){const rows=Array.from(tbl.querySelectorAll("tr"));if(rows.length<2)continue;const hdr=(rows[0]?.textContent||"").toLowerCase();if(!hdr.match(/descri|produto|item|qtd/))continue;const cols=Array.from(rows[0].querySelectorAll("th,td")).map(c=>c.textContent.toLowerCase().trim());const iD=cols.findIndex(c=>c.match(/descri|produto|item/))??0;const iQ=cols.findIndex(c=>c.match(/qtd|quan/));const iU=cols.findIndex(c=>c.match(/unit|vl\s*un/));const iT=cols.findIndex(c=>c.match(/total|vl\s*item/));for(let i=1;i<rows.length;i++){const cells=Array.from(rows[i].querySelectorAll("td"));if(cells.length<3)continue;const desc=cells[iD>=0?iD:0]?.textContent?.trim()||"";if(!desc||desc.length<2)continue;const qty=pBRL(cells[iQ>=0?iQ:1]?.textContent)||1;const unit=pBRL(cells[iU>=0?iU:2]?.textContent)||0;const total=pBRL(cells[iT>=0?iT:cells.length-1]?.textContent)||qty*unit;if(total>0||unit>0)items.push({id:Date.now()+i,desc,qty,unit:unit||(total/qty),total});}if(items.length)break;}const tm=body.match(/total[:\s]+R?\$?\s*([\d\.,]+)/i);const total=tm?pBRL(tm[1]):items.reduce((s,i)=>s+i.total,0);const chave=(url.match(/(\d{44})/)||body.match(/(\d{44})/))?.[1]||null;return{emitente:emitente.slice(0,70),dataEmissao,items:items.length?items:[{id:Date.now(),desc:"",qty:1,unit:0,total:0}],total,chave,sourceUrl:url,parsedOk:items.length>0}; };

const exportXLSX = (purchases,filtered) => {
  const wb=XLSX.utils.book_new();
  const resumo=filtered.map(p=>({"Data":fmtD(p.dataEmissao),"Fornecedor":p.emitente,"Itens":p.items?.length||0,"Total (R$)":p.total,"Chave NF-e":p.chave||""}));
  resumo.push({"Data":"","Fornecedor":"TOTAL","Itens":"","Total (R$)":filtered.reduce((s,p)=>s+p.total,0),"Chave NF-e":""});
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(resumo),"Resumo");
  const rows=[];filtered.forEach(p=>p.items?.forEach(i=>rows.push({"Data":fmtD(p.dataEmissao),"Fornecedor":p.emitente,"Produto":i.desc,"Qtd":i.qty,"Vl Unit (R$)":i.unit,"Total (R$)":i.total})));
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),"Itens");
  const stats=supplierSt(purchases);
  XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(stats.map(s=>({"Fornecedor":s.name,"Compras":s.count,"Total (R$)":s.total,"Ticket Médio (R$)":+(s.total/s.count).toFixed(2)}))),"Fornecedores");
  XLSX.writeFile(wb,`coe_compras_${today()}.xlsx`);
};

/* ═══════════════════════════════════════
   CSS — COÉ BRAND
═══════════════════════════════════════ */
const LOGO_B64 = "data:image/png;base64,";

const CSS = `
  @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Barlow:wght@400;500;600;700;800&family=Barlow+Condensed:wght@600;700;800;900&display=swap');
  *{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent;}
  body{background:#060606;overscroll-behavior:none;}
  ::-webkit-scrollbar{display:none;}
  input,select,button{font-family:'Barlow',sans-serif;outline:none;}
  input{font-size:16px!important;}
  button{touch-action:manipulation;}
  input:focus{border-color:${T.accent}!important;box-shadow:0 0 0 3px ${T.accentDim}!important;}
  @keyframes fadeUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:translateY(0)}}
  @keyframes spin{to{transform:rotate(360deg)}}
  @keyframes scanLine{0%,100%{top:8%}50%{top:88%}}
  @keyframes pop{0%{transform:scale(.92);opacity:0}100%{transform:scale(1);opacity:1}}
  @keyframes glow{0%,100%{box-shadow:0 0 20px ${T.accentGlow}}50%{box-shadow:0 0 40px ${T.accentGlow},0 0 60px rgba(201,228,25,.1)}}
  .fu{animation:fadeUp .28s ease both;}
  .fu1{animation:fadeUp .28s .06s ease both;}
  .fu2{animation:fadeUp .28s .12s ease both;}
  .fu3{animation:fadeUp .28s .18s ease both;}
  .fu4{animation:fadeUp .28s .24s ease both;}
  .pop{animation:pop .22s ease both;}
`;

/* ═══════════════════════════════════════
   COMPONENTS
═══════════════════════════════════════ */
const Btn = ({ch,onClick,variant="primary",full,sm,disabled,style={}}) => (
  <button onClick={onClick} disabled={disabled} style={{
    display:"flex",alignItems:"center",justifyContent:"center",gap:6,
    background: variant==="primary"?T.accent : variant==="danger"?T.red : variant==="ghost"?"transparent" : T.card,
    color: variant==="primary"?"#000" : variant==="danger"?"#fff" : T.text,
    border: variant==="ghost"||variant==="secondary" ? `1px solid ${T.border}` : "none",
    borderRadius:10, padding:sm?"10px 16px":"13px 20px",
    fontWeight:800, fontSize:sm?13:14, letterSpacing:.5,
    fontFamily:"'Barlow Condensed',sans-serif",
    textTransform:"uppercase",
    opacity:disabled?.45:1, width:full?"100%":"auto",
    transition:"all .15s", WebkitUserSelect:"none",
    ...style,
  }}>{ch}</button>
);

const Inp = ({label,value,onChange,type="text",placeholder,prefix}) => (
  <div style={{display:"flex",flexDirection:"column",gap:6}}>
    {label&&<label style={{fontSize:11,fontWeight:700,color:T.sub,textTransform:"uppercase",letterSpacing:.9,fontFamily:"'Barlow Condensed'"}}>{label}</label>}
    <div style={{position:"relative",display:"flex",alignItems:"center"}}>
      {prefix&&<span style={{position:"absolute",left:12,color:T.sub,fontSize:14,pointerEvents:"none"}}>{prefix}</span>}
      <input type={type} value={value} onChange={onChange} placeholder={placeholder}
        style={{background:T.surf,border:`1px solid ${T.border}`,borderRadius:10,color:T.text,fontSize:16,padding:prefix?"12px 14px 12px 36px":"12px 14px",width:"100%",transition:"all .15s"}}/>
    </div>
  </div>
);

const Chip = ({label,active,onClick}) => (
  <button onClick={onClick} style={{
    padding:"8px 16px",borderRadius:8,border:"none",fontWeight:800,fontSize:13,flexShrink:0,
    fontFamily:"'Barlow Condensed',sans-serif",textTransform:"uppercase",letterSpacing:.5,
    background:active?T.accent:T.card, color:active?"#000":T.sub, transition:"all .15s",
  }}>{label}</button>
);

const Tip = ({active,payload,label}) => {
  if(!active||!payload?.length) return null;
  return <div style={{background:T.cardHi||"#181818",border:`1px solid ${T.accent}40`,borderRadius:10,padding:"10px 14px",boxShadow:`0 4px 24px ${T.accentDim}`}}>
    <div style={{fontSize:11,color:T.sub,marginBottom:3}}>{label}</div>
    <div style={{color:T.accent,fontWeight:800,fontSize:16,fontFamily:"'Bebas Neue'"}}>{fmt(payload[0].value)}</div>
  </div>;
};

/* ─── KPI Card ─── */
const KPI = ({label,value,sub,color=T.accent,icon,delay="0s"}) => (
  <div className="fu" style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:"16px",position:"relative",overflow:"hidden",animationDelay:delay}}>
    <div style={{position:"absolute",bottom:-8,right:-6,fontSize:54,opacity:.06,userSelect:"none"}}>{icon}</div>
    <div style={{position:"absolute",top:0,left:0,right:0,height:2,background:color}}/>
    <div style={{fontSize:10,fontWeight:700,color:T.sub,textTransform:"uppercase",letterSpacing:1,fontFamily:"'Barlow Condensed'",marginBottom:8}}>{label}</div>
    <div style={{fontSize:26,fontWeight:400,color,letterSpacing:.5,fontFamily:"'Bebas Neue'"}}>{value}</div>
    {sub&&<div style={{fontSize:11,color:T.sub,marginTop:4}}>{sub}</div>}
  </div>
);

/* ═══════════════════════════════════════
   LOGO COMPONENT
═══════════════════════════════════════ */
const Logo = ({size=38, showSub=true}) => (
  <div style={{display:"flex",alignItems:"center",gap:10}}>
    <img src={LOGO_B64} alt="Coé Burguer" style={{height:size,width:size,objectFit:"contain",filter:"drop-shadow(0 0 10px rgba(201,228,25,0.5))"}}/>
    {showSub && <div style={{fontFamily:"'Barlow Condensed'",fontSize:10,color:T.sub,letterSpacing:1,textTransform:"uppercase"}}>Gestor de Compras</div>}
  </div>
);

/* ═══════════════════════════════════════
   DASHBOARD
═══════════════════════════════════════ */
function Dashboard({purchases,onAdd}) {
  const total  = purchases.reduce((s,p)=>s+p.total,0);
  const now    = new Date(); const ym=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;
  const month  = purchases.filter(p=>p.dataEmissao?.startsWith(ym));
  const mTotal = month.reduce((s,p)=>s+p.total,0);
  const supp   = supplierSt(purchases);
  const monthly= byMonth(purchases);
  const pie    = supp.slice(0,5).map((s,i)=>({name:s.name.split(" ")[0],value:s.total,fill:PALETTE[i]}));
  const alerts = genAlerts(purchases);

  return <div style={{display:"flex",flexDirection:"column",gap:16,paddingBottom:8}}>
    {/* Hero */}
    <div className="fu" style={{
      background:`linear-gradient(135deg,#111 0%,#0a0a0a 100%)`,
      border:`1px solid ${T.accent}30`,borderRadius:20,padding:"24px 20px",
      position:"relative",overflow:"hidden",
    }}>
      <div style={{position:"absolute",top:-30,right:-30,width:180,height:180,borderRadius:"50%",background:T.accentGlow,filter:"blur(60px)",pointerEvents:"none"}}/>
      <div style={{position:"relative"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16}}>
          <img src={LOGO_B64} alt="Coé Burguer" style={{height:60,objectFit:"contain",filter:"drop-shadow(0 0 12px rgba(201,228,25,0.6))"}}/>
          <div style={{fontFamily:"'Barlow Condensed'",fontSize:10,fontWeight:700,color:T.sub,textTransform:"uppercase",letterSpacing:1.5,textAlign:"right"}}>Gestor de<br/>Compras</div>
        </div>
        <div style={{fontFamily:"'Barlow Condensed'",fontSize:11,fontWeight:700,color:T.accent,textTransform:"uppercase",letterSpacing:2,marginBottom:8}}>Total em Compras</div>
        <div style={{fontFamily:"'Bebas Neue'",fontSize:46,letterSpacing:1,color:T.text,lineHeight:1}}>{fmt(total)}</div>
        <div style={{fontSize:13,color:T.sub,marginTop:8,fontFamily:"'Barlow'"}}>{purchases.length} nota{purchases.length!==1?"s":""} · {supp.length} fornecedor{supp.length!==1?"es":""}</div>
        {alerts.length>0&&(
          <div style={{marginTop:14,display:"inline-flex",alignItems:"center",gap:8,background:T.redDim,border:`1px solid ${T.red}40`,borderRadius:8,padding:"8px 14px"}}>
            <span style={{fontSize:14}}>🔔</span>
            <span style={{fontFamily:"'Barlow Condensed'",fontWeight:800,color:T.red,fontSize:14,letterSpacing:.5}}>{alerts.length} ALERTA{alerts.length!==1?"S":""} DE PREÇO</span>
          </div>
        )}
      </div>
    </div>

    {/* KPIs */}
    <div className="fu1" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
      <KPI label="Este Mês"      value={fmt(mTotal)}                                     color={T.accent} icon="📅" delay=".05s"/>
      <KPI label="Ticket Médio"  value={fmt(purchases.length?total/purchases.length:0)}  color="#60A5FA"  icon="🎯" delay=".10s"/>
      <KPI label="Fornecedores"  value={supp.length}                                     color={T.orange} icon="🏪" delay=".15s"/>
      <KPI label="Produtos"      value={new Set(purchases.flatMap(p=>p.items?.map(i=>normN(i.desc))||[])).size} color="#FFD000" icon="📦" delay=".20s"/>
    </div>

    {/* Bar chart */}
    <div className="fu2" style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:18,padding:"20px 14px 12px"}}>
      <div style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:16,letterSpacing:1,textTransform:"uppercase",color:T.text,marginBottom:16}}>Gastos Mensais</div>
      {monthly.length>0?(
        <ResponsiveContainer width="100%" height={160}>
          <BarChart data={monthly} barSize={24} margin={{left:-20,right:4}}>
            <XAxis dataKey="m" tick={{fill:T.sub,fontSize:10,fontFamily:"Barlow"}} axisLine={false} tickLine={false}/>
            <YAxis tick={{fill:T.sub,fontSize:10}} axisLine={false} tickLine={false} tickFormatter={v=>`${(v/1000).toFixed(0)}k`}/>
            <Tooltip content={<Tip/>}/>
            <Bar dataKey="v" fill={T.accent} radius={[5,5,0,0]} background={{fill:"#0a0a0a",radius:[5,5,0,0]}}/>
          </BarChart>
        </ResponsiveContainer>
      ):<div style={{height:160,display:"flex",alignItems:"center",justifyContent:"center",color:T.muted,fontFamily:"'Barlow Condensed'",fontSize:14,letterSpacing:1}}>ADICIONE COMPRAS</div>}
    </div>

    {/* Pie */}
    {pie.length>0&&<div className="fu3" style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:18,padding:"20px"}}>
      <div style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:16,letterSpacing:1,textTransform:"uppercase",color:T.text,marginBottom:16}}>Por Fornecedor</div>
      <div style={{display:"flex",alignItems:"center",gap:16}}>
        <ResponsiveContainer width={130} height={130}>
          <PieChart>
            <Pie data={pie} cx="50%" cy="50%" innerRadius={36} outerRadius={60} dataKey="value" stroke="none">
              {pie.map((e,i)=><Cell key={i} fill={e.fill}/>)}
            </Pie>
            <Tooltip content={<Tip/>}/>
          </PieChart>
        </ResponsiveContainer>
        <div style={{flex:1,display:"flex",flexDirection:"column",gap:9}}>
          {pie.map((e,i)=>(
            <div key={i} style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <div style={{width:8,height:8,borderRadius:2,background:e.fill}}/>
                <span style={{fontSize:12,color:T.sub,fontFamily:"'Barlow'"}}>{e.name}</span>
              </div>
              <span style={{fontSize:13,fontWeight:700,color:T.text,fontFamily:"'Barlow Condensed'"}}>{fmt(e.value)}</span>
            </div>
          ))}
        </div>
      </div>
    </div>}

    {/* Recent */}
    <div className="fu4" style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:18,overflow:"hidden"}}>
      <div style={{padding:"16px 18px",borderBottom:`1px solid ${T.border}`,fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:16,letterSpacing:1,textTransform:"uppercase"}}>Recentes</div>
      {purchases.length===0
        ?<div style={{padding:32,textAlign:"center",color:T.muted,fontFamily:"'Barlow Condensed'",letterSpacing:1,textTransform:"uppercase",fontSize:13}}>Nenhuma compra ainda</div>
        :purchases.slice(0,4).map((p,i)=>(
          <div key={p.id} style={{padding:"14px 18px",display:"flex",justifyContent:"space-between",alignItems:"center",borderBottom:i<Math.min(purchases.length,4)-1?`1px solid ${T.border}`:"none"}}>
            <div>
              <div style={{fontWeight:700,fontSize:14,color:T.text,marginBottom:3,fontFamily:"'Barlow'"}}>{p.emitente}</div>
              <div style={{fontSize:12,color:T.sub}}>{fmtD(p.dataEmissao)} · {p.items?.length} itens</div>
            </div>
            <div style={{fontFamily:"'Bebas Neue'",fontSize:20,color:T.accent,flexShrink:0,marginLeft:12,letterSpacing:.5}}>{fmt(p.total)}</div>
          </div>
        ))}
    </div>
  </div>;
}

/* ═══════════════════════════════════════
   COMPRAS
═══════════════════════════════════════ */
const QUICK=[{l:"Hoje",s:()=>today(),e:()=>today()},{l:"7d",s:()=>dago(7),e:()=>today()},{l:"30d",s:()=>dago(30),e:()=>today()},{l:"Mês",s:()=>{const d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-01`;},e:()=>today()},{l:"Tudo",s:()=>"",e:()=>""}];

function Compras({purchases,onAdd,onDetail}) {
  const [s,setS]=useState("");const [e,setE]=useState("");const [qi,setQi]=useState(4);
  const setQ=i=>{setQi(i);setS(QUICK[i].s());setE(QUICK[i].e());};
  const filtered=useMemo(()=>filterP(purchases,s,e),[purchases,s,e]);
  const total=filtered.reduce((a,p)=>a+p.total,0);

  return <div style={{display:"flex",flexDirection:"column",gap:14,paddingBottom:8}}>
    <div className="fu" style={{overflowX:"auto",display:"flex",gap:8,paddingBottom:4}}>
      {QUICK.map((q,i)=><Chip key={i} label={q.l} active={qi===i} onClick={()=>setQ(i)}/>)}
    </div>
    <div className="fu1" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10}}>
      <Inp label="De" type="date" value={s} onChange={ev=>{setS(ev.target.value);setQi(-1);}}/>
      <Inp label="Até" type="date" value={e} onChange={ev=>{setE(ev.target.value);setQi(-1);}}/>
    </div>
    {/* Summary */}
    <div className="fu2" style={{background:`linear-gradient(135deg,${T.accentDim},transparent)`,border:`1px solid ${T.accent}30`,borderRadius:14,padding:"16px 18px",display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
      {[{l:"Total",v:fmt(total),c:T.accent},{l:"Notas",v:filtered.length,c:T.text},{l:"Ticket Médio",v:fmt(filtered.length?total/filtered.length:0),c:T.sub}].map(k=>(
        <div key={k.l} style={{textAlign:"center"}}>
          <div style={{fontFamily:"'Barlow Condensed'",fontSize:9,fontWeight:700,color:T.sub,textTransform:"uppercase",letterSpacing:1,marginBottom:4}}>{k.l}</div>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:18,color:k.c,letterSpacing:.5}}>{k.v}</div>
        </div>
      ))}
    </div>
    <div className="fu2" style={{display:"flex",gap:10}}>
      <Btn ch="+ Nova Compra" onClick={onAdd} style={{flex:2}}/>
      <Btn ch="📊 Excel" onClick={()=>exportXLSX(purchases,filtered)} variant="secondary" style={{flex:1}}/>
    </div>
    <div className="fu3" style={{display:"flex",flexDirection:"column",gap:8}}>
      {filtered.length===0
        ?<div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:40,textAlign:"center",color:T.muted,fontFamily:"'Barlow Condensed'",letterSpacing:1,textTransform:"uppercase",fontSize:13}}>Nenhuma compra no período</div>
        :[...filtered].sort((a,b)=>(b.dataEmissao||"").localeCompare(a.dataEmissao||"")).map(p=>(
          <div key={p.id} onClick={()=>onDetail(p.id)} style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:"16px",display:"flex",justifyContent:"space-between",alignItems:"center",cursor:"pointer",WebkitUserSelect:"none",transition:"border-color .15s"}}
            onTouchStart={e=>e.currentTarget.style.borderColor=T.accent}
            onTouchEnd={e=>e.currentTarget.style.borderColor=T.border}>
            <div>
              <div style={{fontWeight:700,fontSize:15,color:T.text,marginBottom:4,fontFamily:"'Barlow'"}}>{p.emitente}</div>
              <div style={{fontSize:12,color:T.sub}}>{fmtD(p.dataEmissao)} · {p.items?.length} itens</div>
            </div>
            <div style={{textAlign:"right",flexShrink:0,marginLeft:12}}>
              <div style={{fontFamily:"'Bebas Neue'",fontSize:22,color:T.accent,letterSpacing:.5}}>{fmt(p.total)}</div>
              <div style={{fontSize:11,color:T.muted,marginTop:2}}>ver →</div>
            </div>
          </div>
        ))}
    </div>
  </div>;
}

/* ═══════════════════════════════════════
   FORNECEDORES
═══════════════════════════════════════ */
function Fornecedores({purchases}) {
  const [search,setSearch]=useState("");
  const supp=useMemo(()=>supplierSt(purchases),[purchases]);
  const comp=useMemo(()=>productCmp(supp),[supp]);
  const filtered=comp.filter(p=>!search||p.desc.toLowerCase().includes(search.toLowerCase()));

  return <div style={{display:"flex",flexDirection:"column",gap:14,paddingBottom:8}}>
    <div className="fu" style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:16,letterSpacing:1,textTransform:"uppercase",color:T.text}}>Fornecedores ({supp.length})</div>
    {supp.length===0
      ?<div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:40,textAlign:"center",color:T.muted,fontFamily:"'Barlow Condensed'",letterSpacing:1,textTransform:"uppercase",fontSize:13}}>Nenhum fornecedor ainda</div>
      :supp.map((s,i)=>{
        const pct=supp[0].total>0?(s.total/supp[0].total)*100:0;
        return <div key={s.name} className={`fu${Math.min(i,4)}`} style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:"18px"}}>
          <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:14}}>
            <div style={{width:42,height:42,borderRadius:10,background:PALETTE[i%7]+"22",color:PALETTE[i%7],display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Bebas Neue'",fontSize:22,flexShrink:0}}>{s.name.charAt(0).toUpperCase()}</div>
            <div>
              <div style={{fontWeight:700,fontSize:15,color:T.text,fontFamily:"'Barlow'"}}>{s.name}</div>
              <div style={{fontSize:12,color:T.sub}}>{s.count} compra{s.count!==1?"s":""}</div>
            </div>
          </div>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:28,color:T.accent,letterSpacing:.5,marginBottom:4}}>{fmt(s.total)}</div>
          <div style={{fontSize:12,color:T.sub,marginBottom:12}}>Ticket médio: {fmt(s.total/s.count)}</div>
          <div style={{background:T.surf||"#0C0C0C",borderRadius:4,height:4}}>
            <div style={{background:PALETTE[i%7],height:"100%",borderRadius:4,width:`${pct}%`}}/>
          </div>
        </div>;
      })}

    <div style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:16,letterSpacing:1,textTransform:"uppercase",color:T.text,marginTop:8}}>Comparativo de Preços</div>
    <Inp value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar produto..." prefix="🔍"/>
    {comp.length===0
      ?<div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:32,textAlign:"center"}}>
        <div style={{fontSize:28,marginBottom:10}}>🔍</div>
        <div style={{color:T.sub,fontSize:13}}>Compre o mesmo produto de fornecedores diferentes para ver o comparativo</div>
      </div>
      :filtered.map((p,i)=>{
        const best=p.uniq.reduce((a,b)=>a.unit<b.unit?a:b);
        const worst=p.uniq.reduce((a,b)=>a.unit>b.unit?a:b);
        return <div key={i} style={{background:T.card,border:`1px solid ${p.pct>20?T.red+"40":p.pct>10?"#FFD00040":T.accent+"30"}`,borderRadius:14,padding:"16px"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14}}>
            <div style={{fontWeight:700,fontSize:14,color:T.text,flex:1,marginRight:8,fontFamily:"'Barlow'"}}>{p.desc}</div>
            <span style={{background:p.pct>20?T.redDim:p.pct>10?T.yellowDim:T.accentDim,color:p.pct>20?T.red:p.pct>10?T.yellow:T.accent,padding:"4px 10px",borderRadius:6,fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:13,letterSpacing:.5,flexShrink:0}}>+{p.pct.toFixed(0)}%</span>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8}}>
            {[{l:"Menor",v:fmt(p.min),c:T.accent,n:best.supplier.split(" ")[0]},{l:"Maior",v:fmt(p.max),c:T.red,n:worst.supplier.split(" ")[0]},{l:"Diferença",v:fmt(p.diff),c:T.yellow,n:`${p.uniq.length} fornec.`}].map(k=>(
              <div key={k.l} style={{background:T.surf||"#0C0C0C",borderRadius:10,padding:"12px 10px"}}>
                <div style={{fontFamily:"'Barlow Condensed'",fontSize:9,fontWeight:700,color:T.sub,textTransform:"uppercase",letterSpacing:1,marginBottom:6}}>{k.l}</div>
                <div style={{fontFamily:"'Bebas Neue'",fontSize:18,color:k.c,letterSpacing:.5,marginBottom:4}}>{k.v}</div>
                <div style={{fontSize:10,color:T.sub}}>{k.n}</div>
              </div>
            ))}
          </div>
        </div>;
      })}
  </div>;
}

/* ═══════════════════════════════════════
   ALERTAS
═══════════════════════════════════════ */
function Alertas({purchases}) {
  const alerts=useMemo(()=>genAlerts(purchases),[purchases]);
  return <div style={{display:"flex",flexDirection:"column",gap:14,paddingBottom:8}}>
    <div className="fu" style={{background:alerts.length>0?T.redDim:T.accentDim,border:`1px solid ${alerts.length>0?T.red:T.accent}30`,borderRadius:14,padding:"18px",display:"flex",alignItems:"center",gap:14}}>
      <span style={{fontSize:32}}>{alerts.length>0?"🚨":"✅"}</span>
      <div>
        <div style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:18,letterSpacing:1,textTransform:"uppercase",color:alerts.length>0?T.red:T.accent}}>{alerts.length>0?`${alerts.length} Alerta${alerts.length!==1?"s":""} de Alta`:"Preços Estáveis"}</div>
        <div style={{fontSize:12,color:T.sub,marginTop:3}}>{alerts.length>0?"Produtos acima da média histórica":"Sem variações relevantes detectadas"}</div>
      </div>
    </div>
    {purchases.length<2&&alerts.length===0&&(
      <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,padding:32,textAlign:"center"}}>
        <div style={{fontSize:32,marginBottom:12}}>📊</div>
        <div style={{color:T.sub,fontSize:13,fontFamily:"'Barlow'"}}>Adicione mais compras do mesmo produto para detectar variações de preço automaticamente.</div>
      </div>
    )}
    {alerts.map((a,i)=>{
      const sev={high:{c:T.red,bg:T.redDim,l:"ALTA"},medium:{c:T.yellow,bg:T.yellowDim,l:"MÉDIA"},low:{c:T.accent,bg:T.accentDim,l:"BAIXA"}}[a.severity]||{c:T.accent,bg:T.accentDim,l:"BAIXA"};
      return <div key={i} className={`fu${Math.min(i,4)}`} style={{background:T.card,border:`1px solid ${sev.c}40`,borderRadius:14,padding:"18px"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:14}}>
          <div style={{fontWeight:700,fontSize:15,color:T.text,flex:1,marginRight:10,fontFamily:"'Barlow'"}}>{a.desc}</div>
          <span style={{background:sev.bg,color:sev.c,padding:"4px 12px",borderRadius:6,fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:12,letterSpacing:1}}>RISCO {sev.l}</span>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:8,marginBottom:14}}>
          {[{l:"Preço Atual",v:fmt(a.latest),c:T.red},{l:"Média Histórica",v:fmt(a.avg),c:T.accent},{l:"Variação",v:`+${a.pct.toFixed(1)}%`,c:T.yellow}].map(k=>(
            <div key={k.l} style={{background:T.surf||"#0C0C0C",borderRadius:10,padding:"12px 10px",textAlign:"center"}}>
              <div style={{fontFamily:"'Barlow Condensed'",fontSize:9,fontWeight:700,color:T.sub,textTransform:"uppercase",letterSpacing:1,marginBottom:6}}>{k.l}</div>
              <div style={{fontFamily:"'Bebas Neue'",fontSize:20,color:k.c,letterSpacing:.5}}>{k.v}</div>
            </div>
          ))}
        </div>
        <div style={{borderTop:`1px solid ${T.border}`,paddingTop:10,fontSize:12,color:T.sub,display:"flex",gap:16}}>
          <span>📅 {fmtD(a.date)}</span>
          <span>🏪 {a.supplier.split(" ")[0]}</span>
        </div>
      </div>;
    })}
  </div>;
}

/* ═══════════════════════════════════════
   ADD PURCHASE
═══════════════════════════════════════ */
function AddPurchase({onFound,onManual}) {
  const [tab,setTab]=useState("scan");const [scanning,setScanning]=useState(false);const [loading,setLoading]=useState(false);const [error,setError]=useState(null);const [urlInput,setUrlInput]=useState("");const [jsQR,setJsQR]=useState(false);
  const [manual,setManual]=useState({emitente:"",dataEmissao:today(),items:[{id:1,desc:"",qty:1,unit:0,total:0}]});
  const vidR=useRef(),cvR=useRef(),strR=useRef(),intR=useRef(),fileR=useRef();
  useEffect(()=>{if(window.jsQR){setJsQR(true);return;}const s=document.createElement("script");s.src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js";s.onload=()=>setJsQR(true);document.head.appendChild(s);},[]);
  const stop=useCallback(()=>{clearInterval(intR.current);strR.current?.getTracks().forEach(t=>t.stop());strR.current=null;setScanning(false);},[]);
  useEffect(()=>()=>stop(),[stop]);
  const startCam=async()=>{setError(null);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"environment"}});strR.current=stream;vidR.current.srcObject=stream;await vidR.current.play();setScanning(true);intR.current=setInterval(()=>{if(!vidR.current||!cvR.current||!window.jsQR)return;const v=vidR.current;if(v.readyState<2)return;const c=cvR.current;c.width=v.videoWidth;c.height=v.videoHeight;const ctx=c.getContext("2d");ctx.drawImage(v,0,0);const id=ctx.getImageData(0,0,c.width,c.height);const code=window.jsQR(id.data,id.width,id.height,{inversionAttempts:"dontInvert"});if(code?.data){stop();handleQR(code.data);}},250);}catch(_){setError("Câmera indisponível. Use Upload ou cole a URL.");}};
  const handleQR=async url=>{if(!url.startsWith("http")){setError("QR Code não reconhecido como NF-e.");return;}setLoading(true);setError(null);try{const r=await fetch(`https://api.allorigins.win/get?url=${encodeURIComponent(url)}`,{signal:AbortSignal.timeout(18000)});const d=await r.json();if(!d.contents)throw new Error();onFound(parseNFe(d.contents,url));}catch(_){setError("SEFAZ bloqueou ou timeout. Cole a URL ou use entrada manual.");setUrlInput(url);setTab("url");}finally{setLoading(false);};};
  const handleFile=e=>{const f=e.target.files?.[0];if(!f)return;if(!window.jsQR){setError("Aguardando biblioteca...");return;}const r=new FileReader();r.onload=ev=>{const img=new Image();img.onload=()=>{const c=document.createElement("canvas");c.width=img.width;c.height=img.height;c.getContext("2d").drawImage(img,0,0);const id=c.getContext("2d").getImageData(0,0,c.width,c.height);const code=window.jsQR(id.data,id.width,id.height);if(code?.data)handleQR(code.data);else setError("QR Code não encontrado na imagem.");};img.src=ev.target.result;};r.readAsDataURL(f);e.target.value="";};
  const addI=()=>setManual(m=>({...m,items:[...m.items,{id:Date.now(),desc:"",qty:1,unit:0,total:0}]}));
  const remI=id=>setManual(m=>({...m,items:m.items.filter(i=>i.id!==id)}));
  const updI=(id,f,v)=>setManual(m=>{const items=m.items.map(i=>{if(i.id!==id)return i;const u={...i,[f]:v};if(f==="qty"||f==="unit")u.total=Number(u.qty)*Number(u.unit);return u;});return{...m,items};});

  const TABS=[{id:"scan",icon:"📷",l:"Câmera"},{id:"upload",icon:"🖼️",l:"Imagem"},{id:"url",icon:"🔗",l:"URL"},{id:"manual",icon:"✏️",l:"Manual"}];

  return <div style={{display:"flex",flexDirection:"column",gap:16,paddingBottom:8}}>
    <div className="fu" style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:4,background:T.surf||"#0C0C0C",borderRadius:12,padding:4,border:`1px solid ${T.border}`}}>
      {TABS.map(t=><button key={t.id} onClick={()=>{setTab(t.id);stop();setError(null);}} style={{padding:"10px 4px",borderRadius:9,border:"none",fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:12,letterSpacing:.5,textTransform:"uppercase",background:tab===t.id?T.accent:"transparent",color:tab===t.id?"#000":T.sub,transition:"all .15s"}}>{t.icon} {t.l}</button>)}
    </div>
    {error&&<div className="pop" style={{background:T.redDim,border:`1px solid ${T.red}30`,borderRadius:10,padding:"12px 14px",fontSize:13,color:T.red}}>⚠️ {error}</div>}
    {loading&&<div style={{textAlign:"center",padding:"48px 20px",color:T.sub}}><div style={{fontSize:28,animation:"spin 1.2s linear infinite",display:"inline-block",marginBottom:14}}>⏳</div><div style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:16,letterSpacing:1,color:T.sub}}>BUSCANDO NOTA FISCAL...</div></div>}

    {!loading&&<>
      {tab==="scan"&&<div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:16}}>
        <div style={{width:"100%",maxWidth:320,aspectRatio:"1",background:"#000",border:`2px solid ${scanning?T.accent:T.border}`,borderRadius:20,overflow:"hidden",position:"relative",transition:"border-color .3s",boxShadow:scanning?`0 0 30px ${T.accentGlow}`:"none"}}>
          <video ref={vidR} style={{width:"100%",height:"100%",objectFit:"cover"}} playsInline muted/>
          <canvas ref={cvR} style={{display:"none"}}/>
          {scanning&&<>
            {[["tl"],["tr"],["bl"],["br"]].map(([k])=>(
              <div key={k} style={{position:"absolute",width:28,height:28,top:["tl","tr"].includes(k)?16:"auto",bottom:["bl","br"].includes(k)?16:"auto",left:["tl","bl"].includes(k)?16:"auto",right:["tr","br"].includes(k)?16:"auto",borderTop:["tl","tr"].includes(k)?`3px solid ${T.accent}`:"none",borderBottom:["bl","br"].includes(k)?`3px solid ${T.accent}`:"none",borderLeft:["tl","bl"].includes(k)?`3px solid ${T.accent}`:"none",borderRight:["tr","br"].includes(k)?`3px solid ${T.accent}`:"none"}}/>
            ))}
            <div style={{position:"absolute",left:"10%",right:"10%",height:2,background:`linear-gradient(90deg,transparent,${T.accent},transparent)`,animation:"scanLine 2s ease-in-out infinite"}}/>
          </>}
          {!scanning&&<div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:10,color:T.muted}}><span style={{fontSize:44}}>📷</span><span style={{fontFamily:"'Barlow Condensed'",letterSpacing:1,fontSize:13,textTransform:"uppercase"}}>Câmera desligada</span></div>}
        </div>
        <Btn ch={scanning?"⏹ Parar":"▶ Iniciar Câmera"} onClick={scanning?stop:startCam} variant={scanning?"secondary":"primary"} style={{width:220}}/>
        <div style={{fontSize:12,color:T.muted,textAlign:"center",fontFamily:"'Barlow'"}}>Aponte para o QR Code da NFC-e</div>
      </div>}

      {tab==="upload"&&<div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:16}}>
        <div onClick={()=>fileR.current?.click()} style={{width:"100%",aspectRatio:"1.6",background:"#000",border:`2px dashed ${T.border}`,borderRadius:18,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:10,cursor:"pointer",color:T.muted}}>
          <span style={{fontSize:44}}>🖼️</span>
          <span style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:14,letterSpacing:1,textTransform:"uppercase"}}>Toque para selecionar</span>
          <span style={{fontSize:12}}>Foto do QR Code da nota</span>
        </div>
        <input ref={fileR} type="file" accept="image/*" capture="environment" style={{display:"none"}} onChange={handleFile}/>
      </div>}

      {tab==="url"&&<div style={{display:"flex",flexDirection:"column",gap:14}}>
        <div style={{background:T.accentDim,border:`1px solid ${T.accent}30`,borderRadius:10,padding:"12px 14px",fontSize:13,color:T.accent}}>
          💡 Escaneie com a câmera do celular → copie a URL → cole aqui
        </div>
        <Inp label="URL da NFC-e" value={urlInput} onChange={e=>setUrlInput(e.target.value)} placeholder="https://www.sefaz.XX.gov.br/..."/>
        <Btn ch="Buscar Nota Fiscal" onClick={()=>urlInput&&handleQR(urlInput)} disabled={!urlInput} full/>
      </div>}

      {tab==="manual"&&<div style={{display:"flex",flexDirection:"column",gap:14}}>
        <Inp label="Fornecedor" value={manual.emitente} onChange={e=>setManual(m=>({...m,emitente:e.target.value}))} placeholder="Nome do fornecedor"/>
        <Inp label="Data da Compra" type="date" value={manual.dataEmissao} onChange={e=>setManual(m=>({...m,dataEmissao:e.target.value}))}/>
        <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,overflow:"hidden"}}>
          <div style={{padding:"14px 16px",borderBottom:`1px solid ${T.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <span style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:15,letterSpacing:1,textTransform:"uppercase"}}>Produtos</span>
            <button onClick={addI} style={{background:T.accentDim,color:T.accent,border:"none",borderRadius:8,padding:"7px 14px",fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:13,letterSpacing:.5}}>+ ITEM</button>
          </div>
          {manual.items.map((item,i)=>(
            <div key={item.id} style={{padding:"12px 14px",borderBottom:i<manual.items.length-1?`1px solid ${T.border}`:"none"}}>
              <input value={item.desc} placeholder="Nome do produto" onChange={e=>updI(item.id,"desc",e.target.value)}
                style={{background:T.cardHi||"#181818",border:`1px solid ${T.border}`,borderRadius:9,color:T.text,fontSize:14,padding:"10px 12px",width:"100%",marginBottom:8,fontFamily:"'Barlow'"}}/>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr auto",gap:8,alignItems:"center"}}>
                <div>
                  <div style={{fontFamily:"'Barlow Condensed'",fontSize:9,fontWeight:700,color:T.sub,marginBottom:4,letterSpacing:1}}>QUANTIDADE</div>
                  <input type="number" value={item.qty} min="0" step="0.001" onChange={e=>updI(item.id,"qty",e.target.value)}
                    style={{background:T.cardHi||"#181818",border:`1px solid ${T.border}`,borderRadius:9,color:T.text,fontSize:14,padding:"10px",width:"100%",textAlign:"center",fontFamily:"'Barlow'"}}/>
                </div>
                <div>
                  <div style={{fontFamily:"'Barlow Condensed'",fontSize:9,fontWeight:700,color:T.sub,marginBottom:4,letterSpacing:1}}>VL. UNIT.</div>
                  <input type="number" value={item.unit} min="0" step="0.01" onChange={e=>updI(item.id,"unit",e.target.value)}
                    style={{background:T.cardHi||"#181818",border:`1px solid ${T.border}`,borderRadius:9,color:T.text,fontSize:14,padding:"10px",width:"100%",textAlign:"right",fontFamily:"'Barlow'"}}/>
                </div>
                {manual.items.length>1&&<button onClick={()=>remI(item.id)} style={{background:T.redDim,border:"none",borderRadius:8,color:T.red,fontSize:16,padding:"10px 8px",marginTop:18}}>✕</button>}
              </div>
              <div style={{textAlign:"right",fontFamily:"'Bebas Neue'",fontSize:18,color:T.accent,marginTop:8,letterSpacing:.5}}>{fmt(item.total)}</div>
            </div>
          ))}
          <div style={{padding:"14px 16px",background:T.accentDim,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <span style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:14,letterSpacing:1,color:T.sub}}>TOTAL</span>
            <span style={{fontFamily:"'Bebas Neue'",fontSize:24,color:T.accent,letterSpacing:.5}}>{fmt(manual.items.reduce((s,i)=>s+i.total,0))}</span>
          </div>
        </div>
        <Btn ch="Revisar e Salvar" onClick={()=>{if(!manual.emitente){setError("Informe o fornecedor.");return;}onManual({...manual,total:manual.items.reduce((s,i)=>s+i.total,0),parsedOk:true});}} full/>
      </div>}
    </>}
  </div>;
}

/* ═══════════════════════════════════════
   REVIEW
═══════════════════════════════════════ */
function Review({nf,setNf,onConfirm,onBack}) {
  const updI=(id,f,v)=>{const items=nf.items.map(i=>{if(i.id!==id)return i;const u={...i,[f]:v};if(f==="qty"||f==="unit")u.total=Number(u.qty)*Number(u.unit);return u;});setNf({...nf,items,total:items.reduce((s,i)=>s+i.total,0)});};
  const addI=()=>setNf(n=>({...n,items:[...n.items,{id:Date.now(),desc:"",qty:1,unit:0,total:0}]}));
  const remI=id=>{const items=nf.items.filter(i=>i.id!==id);setNf({...nf,items,total:items.reduce((s,i)=>s+i.total,0)});};
  return <div style={{display:"flex",flexDirection:"column",gap:16,paddingBottom:8}}>
    <div className="pop" style={{background:nf.parsedOk?T.accentDim:T.yellowDim,border:`1px solid ${nf.parsedOk?T.accent:T.yellow}30`,borderRadius:10,padding:"12px 14px",fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:14,letterSpacing:.5,color:nf.parsedOk?T.accent:T.yellow}}>
      {nf.parsedOk?"✓ NOTA LIDA COM SUCESSO — REVISE ANTES DE SALVAR":"⚠️ DADOS PARCIAIS — PREENCHA OS CAMPOS EM BRANCO"}
    </div>
    <Inp label="Fornecedor" value={nf.emitente} onChange={e=>setNf({...nf,emitente:e.target.value})}/>
    <Inp label="Data" type="date" value={nf.dataEmissao} onChange={e=>setNf({...nf,dataEmissao:e.target.value})}/>
    <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,overflow:"hidden"}}>
      <div style={{padding:"14px 16px",borderBottom:`1px solid ${T.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <span style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:15,letterSpacing:1,textTransform:"uppercase"}}>Produtos ({nf.items.length})</span>
        <button onClick={addI} style={{background:T.accentDim,color:T.accent,border:"none",borderRadius:8,padding:"7px 14px",fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:13,letterSpacing:.5}}>+ ITEM</button>
      </div>
      {nf.items.map((item,i)=>(
        <div key={item.id} style={{padding:"14px",borderBottom:i<nf.items.length-1?`1px solid ${T.border}`:"none",background:i%2?"rgba(201,228,25,.02)":"transparent"}}>
          <div style={{display:"flex",gap:8,marginBottom:8}}>
            <input value={item.desc} onChange={e=>updI(item.id,"desc",e.target.value)} placeholder="Produto"
              style={{flex:1,background:T.surf||"#0C0C0C",border:`1px solid ${T.border}`,borderRadius:9,color:T.text,fontSize:14,padding:"10px 12px",fontFamily:"'Barlow'",transition:"all .15s"}}
              onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
            <button onClick={()=>remI(item.id)} style={{background:T.redDim,border:"none",borderRadius:8,color:T.red,fontSize:16,padding:"10px 8px",flexShrink:0}}>✕</button>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8}}>
            <div>
              <div style={{fontFamily:"'Barlow Condensed'",fontSize:9,fontWeight:700,color:T.sub,marginBottom:4,letterSpacing:1}}>QUANTIDADE</div>
              <input type="number" value={item.qty} min="0" step="0.001" onChange={e=>updI(item.id,"qty",parseFloat(e.target.value)||0)}
                style={{width:"100%",background:T.surf||"#0C0C0C",border:`1px solid ${T.border}`,borderRadius:9,color:T.text,fontSize:14,padding:"10px",textAlign:"center",fontFamily:"'Barlow'",transition:"all .15s"}}
                onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
            </div>
            <div>
              <div style={{fontFamily:"'Barlow Condensed'",fontSize:9,fontWeight:700,color:T.sub,marginBottom:4,letterSpacing:1}}>VL. UNITÁRIO</div>
              <input type="number" value={item.unit} min="0" step="0.01" onChange={e=>updI(item.id,"unit",parseFloat(e.target.value)||0)}
                style={{width:"100%",background:T.surf||"#0C0C0C",border:`1px solid ${T.border}`,borderRadius:9,color:T.text,fontSize:14,padding:"10px",textAlign:"right",fontFamily:"'Barlow'",transition:"all .15s"}}
                onFocus={e=>e.target.style.borderColor=T.accent} onBlur={e=>e.target.style.borderColor=T.border}/>
            </div>
          </div>
          <div style={{textAlign:"right",fontFamily:"'Bebas Neue'",fontSize:18,color:T.accent,marginTop:8,letterSpacing:.5}}>{fmt(item.total)}</div>
        </div>
      ))}
      <div style={{padding:"16px",background:T.accentDim,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <span style={{fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:14,letterSpacing:1,color:T.sub}}>TOTAL DA NOTA</span>
        <span style={{fontFamily:"'Bebas Neue'",fontSize:28,color:T.accent,letterSpacing:.5}}>{fmt(nf.total)}</span>
      </div>
    </div>
    <div style={{display:"flex",gap:10}}>
      <Btn ch="Cancelar" onClick={onBack} variant="ghost" style={{flex:1}}/>
      <Btn ch="✓ Salvar Compra" onClick={onConfirm} style={{flex:2}}/>
    </div>
  </div>;
}

/* ═══════════════════════════════════════
   DETAIL
═══════════════════════════════════════ */
function Detail({purchase,onDelete}) {
  if(!purchase) return null;
  return <div style={{display:"flex",flexDirection:"column",gap:14,paddingBottom:8}} className="fu">
    <div style={{background:T.card,border:`1px solid ${T.accent}30`,borderRadius:16,padding:"20px",position:"relative",overflow:"hidden"}}>
      <div style={{position:"absolute",top:-20,right:-20,width:120,height:120,borderRadius:"50%",background:T.accentGlow,filter:"blur(40px)",pointerEvents:"none"}}/>
      <div style={{position:"relative"}}>
        <div style={{fontFamily:"'Barlow Condensed'",fontSize:10,fontWeight:700,color:T.sub,textTransform:"uppercase",letterSpacing:1.2,marginBottom:8}}>Fornecedor</div>
        <div style={{fontFamily:"'Bebas Neue'",fontSize:28,letterSpacing:1,color:T.text,marginBottom:8}}>{purchase.emitente}</div>
        <div style={{fontSize:13,color:T.sub}}>📅 {fmtD(purchase.dataEmissao)} · 📦 {purchase.items?.length} produto{purchase.items?.length!==1?"s":""}</div>
      </div>
    </div>
    <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:14,overflow:"hidden"}}>
      <div style={{padding:"14px 18px",borderBottom:`1px solid ${T.border}`,fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:15,letterSpacing:1,textTransform:"uppercase"}}>Itens da Nota</div>
      {purchase.items?.map((item,i)=>(
        <div key={item.id||i} style={{padding:"14px 18px",display:"flex",justifyContent:"space-between",alignItems:"center",borderBottom:i<purchase.items.length-1?`1px solid ${T.border}`:"none"}}>
          <div style={{flex:1,marginRight:12}}>
            <div style={{fontWeight:600,fontSize:14,color:T.text,marginBottom:3,fontFamily:"'Barlow'"}}>{item.desc||"—"}</div>
            <div style={{fontSize:12,color:T.sub}}>{item.qty} × {fmt(item.unit)}</div>
          </div>
          <div style={{fontFamily:"'Bebas Neue'",fontSize:20,color:T.accent,letterSpacing:.5,flexShrink:0}}>{fmt(item.total)}</div>
        </div>
      ))}
      <div style={{padding:"16px 18px",background:T.accentDim,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
        <span style={{fontFamily:"'Barlow Condensed'",fontWeight:800,letterSpacing:1,color:T.sub}}>TOTAL</span>
        <span style={{fontFamily:"'Bebas Neue'",fontSize:28,color:T.accent,letterSpacing:.5}}>{fmt(purchase.total)}</span>
      </div>
    </div>
    <Btn ch="🗑️ Excluir esta compra" onClick={()=>onDelete(purchase.id)} variant="danger" full/>
  </div>;
}

/* ═══════════════════════════════════════
   BOTTOM NAV
═══════════════════════════════════════ */
const NAV=[
  {id:"dashboard",icon:"◈",label:"INÍCIO"},
  {id:"compras",  icon:"🧾",label:"COMPRAS"},
  {id:"add",      icon:"＋",label:"",fab:true},
  {id:"fornecedores",icon:"🏪",label:"FORNEC."},
  {id:"alertas",  icon:"🔔",label:"ALERTAS"},
];

/* ═══════════════════════════════════════
   APP ROOT
═══════════════════════════════════════ */
export default function App() {
  const [nav,setNav]     = useState("dashboard");
  const [sub,setSub]     = useState(null);
  const [purchases,setP] = useState([]);
  const [nf,setNf]       = useState(null);
  const [detailId,setDId]= useState(null);

  useEffect(()=>{
    const l=document.createElement("link");l.rel="stylesheet";
    l.href="https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Barlow:wght@400;500;600;700;800&family=Barlow+Condensed:wght@600;700;800;900&display=swap";
    document.head.appendChild(l);
  },[]);

  useEffect(()=>{(async()=>{try{const r=await window.storage.get("coe_v1");if(r)setP(JSON.parse(r.value));}catch(_){}})();},[]);
  const save=async list=>{setP(list);try{await window.storage.set("coe_v1",JSON.stringify(list));}catch(_){}};
  const confirm=async()=>{const p={id:Date.now().toString(),...nf,savedAt:new Date().toISOString()};await save([p,...purchases]);setNf(null);setSub(null);setNav("compras");};
  const del=async id=>{await save(purchases.filter(p=>p.id!==id));setSub(null);};
  const goAdd=()=>{setSub(null);setNav("add");};
  const goBack=()=>{setNf(null);setSub(null);};

  const alerts=useMemo(()=>genAlerts(purchases),[purchases]);
  const detail=purchases.find(p=>p.id===detailId);
  const isSub=sub==="review"||sub==="detail";

  const titles={dashboard:"Início",compras:"Compras",add:"Nova Compra",fornecedores:"Fornecedores",alertas:"Alertas"};

  return (
    <div style={{background:T.bg,minHeight:"100vh",fontFamily:"'Barlow',sans-serif",color:T.text,display:"flex",flexDirection:"column",maxWidth:480,margin:"0 auto",position:"relative"}}>
      <style>{CSS}</style>

      {/* Header */}
      <header style={{position:"sticky",top:0,zIndex:100,background:"rgba(6,6,6,0.96)",backdropFilter:"blur(20px)",borderBottom:`1px solid ${T.border}`,padding:"0 16px",height:58,display:"flex",alignItems:"center",justifyContent:"space-between",flexShrink:0}}>
        <div style={{display:"flex",alignItems:"center",gap:10}}>
          {isSub&&<button onClick={goBack} style={{background:"none",border:"none",color:T.sub,fontSize:22,padding:"0 6px 0 0",flexShrink:0}}>←</button>}
          {!isSub&&nav==="dashboard"
            ?<Logo size={40} showSub={false}/>
            :<div style={{fontFamily:"'Bebas Neue'",fontSize:22,letterSpacing:1.5,color:T.text}}>{isSub?(sub==="review"?"REVISAR NOTA":"DETALHE"):titles[nav]?.toUpperCase()}</div>
          }
        </div>
        {nav==="alertas"&&!isSub&&alerts.length>0&&(
          <span style={{background:T.red,color:"#fff",borderRadius:6,padding:"3px 10px",fontFamily:"'Barlow Condensed'",fontWeight:800,fontSize:12,letterSpacing:.5}}>{alerts.length}</span>
        )}
      </header>

      {/* Content */}
      <main style={{flex:1,overflowY:"auto",padding:"16px 16px 90px"}}>
        {!isSub&&nav==="dashboard"&&<Dashboard purchases={purchases} onAdd={goAdd}/>}
        {!isSub&&nav==="compras"&&<Compras purchases={purchases} onAdd={goAdd} onDetail={id=>{setDId(id);setSub("detail");}}/>}
        {!isSub&&nav==="add"&&<AddPurchase onFound={n=>{setNf(n);setSub("review");}} onManual={n=>{setNf(n);setSub("review");}}/>}
        {!isSub&&nav==="fornecedores"&&<Fornecedores purchases={purchases}/>}
        {!isSub&&nav==="alertas"&&<Alertas purchases={purchases}/>}
        {sub==="review"&&nf&&<Review nf={nf} setNf={setNf} onConfirm={confirm} onBack={goBack}/>}
        {sub==="detail"&&<Detail purchase={detail} onDelete={del} onBack={goBack}/>}
      </main>

      {/* Bottom Nav */}
      {!isSub&&(
        <nav style={{position:"fixed",bottom:0,left:"50%",transform:"translateX(-50%)",width:"100%",maxWidth:480,background:"rgba(6,6,6,0.97)",backdropFilter:"blur(24px)",borderTop:`1px solid ${T.border}`,display:"flex",alignItems:"center",justifyContent:"space-around",padding:"8px 0 max(env(safe-area-inset-bottom,0px),8px)",zIndex:100}}>
          {NAV.map(n=>{
            const isA=nav===n.id;
            if(n.fab) return(
              <button key={n.id} onClick={goAdd} style={{width:54,height:54,borderRadius:16,background:T.accent,border:"none",fontSize:24,display:"flex",alignItems:"center",justifyContent:"center",color:"#000",fontWeight:900,transform:"translateY(-8px)",boxShadow:`0 4px 28px ${T.accentGlow},0 0 0 3px #06060660`,animation:"glow 3s ease-in-out infinite",transition:"transform .15s"}}>＋</button>
            );
            return(
              <button key={n.id} onClick={()=>{setSub(null);setNav(n.id);}} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3,background:"none",border:"none",color:isA?T.accent:T.muted,padding:"4px 10px",position:"relative",transition:"color .15s"}}>
                <span style={{fontSize:18,transition:"transform .2s",transform:isA?"scale(1.2)":"scale(1)"}}>{n.icon}</span>
                <span style={{fontFamily:"'Barlow Condensed'",fontSize:9,fontWeight:800,letterSpacing:.8}}>{n.label}</span>
                {n.id==="alertas"&&alerts.length>0&&<span style={{position:"absolute",top:1,right:4,width:7,height:7,borderRadius:"50%",background:T.red}}/>}
                {isA&&<div style={{width:4,height:4,borderRadius:"50%",background:T.accent,marginTop:1}}/>}
              </button>
            );
          })}
        </nav>
      )}
    </div>
  );
}
